import { Method, type MatrixHttpApi, type IHttpOpts } from "../../http-api/index.ts";
import type { IKeyValueStore } from "../../store/KeyValueStore.ts";
import type { IDeviceKeys, IOneTimeKey } from "../../@types/crypto.ts";
import type { KeyBackupInfo } from "../../crypto-api/keybackup.ts";
import { logger } from "../../logger.ts";

export interface CryptoManagerEvents {
    keysUploaded: void;
    keysClaimed: void;
    keyBackupCreated: string;
    keyBackupRestored: void;
    error: Error;
}

export interface UploadKeysOptions {
    deviceKeys?: IDeviceKeys;
    oneTimeKeys?: Record<string, IOneTimeKey>;
    fallbackKeys?: Record<string, IOneTimeKey>;
}

export interface QueryKeysRequest {
    device_keys: Record<string, string[]>;
    timeout?: number;
    token?: string;
}

export interface ClaimKeysRequest {
    one_time_keys: Record<string, Record<string, string>>;
    timeout?: number;
}

export class CryptoManager {
    private deviceKeys: Map<string, IDeviceKeys> = new Map();
    private oneTimeKeys: Map<string, IOneTimeKey> = new Map();
    private keyBackupVersion: string | null = null;

    public constructor(
        private http: MatrixHttpApi<IHttpOpts>,
        private store: IKeyValueStore,
    ) {
        this.loadKeys();
    }

    public async uploadKeys(options: UploadKeysOptions): Promise<{ one_time_key_counts: Record<string, number> }> {
        const body: Record<string, unknown> = {};

        if (options.deviceKeys) {
            body.device_keys = options.deviceKeys;
            this.deviceKeys.set(options.deviceKeys.device_id, options.deviceKeys);
        }

        if (options.oneTimeKeys) {
            body.one_time_keys = options.oneTimeKeys;
            Object.entries(options.oneTimeKeys).forEach(([keyId, key]) => {
                this.oneTimeKeys.set(keyId, key);
            });
        }

        if (options.fallbackKeys) {
            body.fallback_keys = options.fallbackKeys;
        }

        const response = await this.http.authedRequest<{ one_time_key_counts: Record<string, number> }>(
            Method.Post,
            "/keys/upload",
            undefined,
            body,
        );

        await this.saveKeys();
        return response;
    }

    public async queryKeys(request: QueryKeysRequest): Promise<{
        device_keys: Record<string, Record<string, IDeviceKeys>>;
        failures: Record<string, Record<string, Record<string, unknown>>>;
    }> {
        return this.http.authedRequest(Method.Post, "/keys/query", undefined, request);
    }

    public async claimKeys(request: ClaimKeysRequest): Promise<{
        one_time_keys: Record<string, Record<string, IOneTimeKey>>;
        failures: Record<string, Record<string, Record<string, unknown>>>;
    }> {
        const response = await this.http.authedRequest<{
            one_time_keys: Record<string, Record<string, IOneTimeKey>>;
            failures: Record<string, Record<string, Record<string, unknown>>>;
        }>(Method.Post, "/keys/claim", undefined, request);

        Object.entries(response.one_time_keys).forEach((entry: [string, Record<string, IOneTimeKey>]) => {
            const [userId, keys] = entry;
            Object.entries(keys).forEach((keyEntry: [string, IOneTimeKey]) => {
                const [deviceId, key] = keyEntry;
                this.oneTimeKeys.set(`${userId}:${deviceId}`, key);
            });
        });

        await this.saveKeys();
        return response;
    }

    public async getKeyChanges(
        fromToken: string,
        toToken: string,
    ): Promise<{
        changed: string[];
        left: string[];
    }> {
        return this.http.authedRequest(Method.Post, "/keys/changes", undefined, {
            from: fromToken,
            to: toToken,
        });
    }

    public async uploadKeySignatures(
        body: Record<string, Record<string, Record<string, Record<string, unknown>>>>,
    ): Promise<void> {
        await this.http.authedRequest(Method.Post, "/keys/signatures/upload", undefined, body);
    }

    public async getDeviceKey(userId: string, deviceId: string): Promise<IDeviceKeys | undefined> {
        const response = await this.queryKeys({
            device_keys: { [userId]: [deviceId] },
        });
        return response.device_keys[userId]?.[deviceId];
    }

    public async getUserKeys(userIds: string[]): Promise<Record<string, Record<string, IDeviceKeys>>> {
        const deviceKeys: Record<string, string[]> = {};
        userIds.forEach((userId) => {
            deviceKeys[userId] = [];
        });

        const response = await this.queryKeys({ device_keys: deviceKeys });

        Object.entries(response.device_keys).forEach(([userId, keys]) => {
            Object.entries(keys).forEach(([deviceId, key]) => {
                this.deviceKeys.set(`${userId}:${deviceId}`, key);
            });
        });

        await this.saveKeys();
        return response.device_keys;
    }

    public getStoredDeviceKey(userId: string, deviceId: string): IDeviceKeys | undefined {
        return this.deviceKeys.get(`${userId}:${deviceId}`);
    }

    public getStoredOneTimeKey(keyId: string): IOneTimeKey | undefined {
        return this.oneTimeKeys.get(keyId);
    }

    public clearDeviceKey(userId: string, deviceId: string): void {
        this.deviceKeys.delete(`${userId}:${deviceId}`);
        this.saveKeys();
    }

    public clearOneTimeKey(keyId: string): void {
        this.oneTimeKeys.delete(keyId);
        this.saveKeys();
    }

    public async createKeyBackup(
        _version: string,
        algorithm: string,
        authData: Record<string, unknown>,
    ): Promise<Record<string, unknown>> {
        const response = await this.http.authedRequest<{
            version: string;
            algorithm: string;
            auth_data: Record<string, unknown>;
        }>(Method.Post, "/room_keys/version", undefined, {
            algorithm,
            auth_data: authData,
        });

        this.keyBackupVersion = response.version;
        await this.store.setItem("key_backup_version", response.version);

        return response;
    }

    public async getKeyBackup(version?: string): Promise<KeyBackupInfo | null> {
        const path = version ? `/room_keys/version/${version}` : "/room_keys/version";
        try {
            const response = await this.http.authedRequest<KeyBackupInfo>(Method.Get, path);
            this.keyBackupVersion = response.version ?? null;
            await this.store.setItem("key_backup_version", response.version ?? null);
            return response;
        } catch (error) {
            if ((error as { httpStatus?: number }).httpStatus === 404) {
                return null;
            }
            throw error;
        }
    }

    public async updateKeyBackup(version: string, versionData: Partial<KeyBackupInfo>): Promise<KeyBackupInfo> {
        const response = await this.http.authedRequest<KeyBackupInfo>(
            Method.Put,
            `/room_keys/version/${version}`,
            undefined,
            versionData,
        );

        this.keyBackupVersion = response.version ?? null;
        await this.store.setItem("key_backup_version", response.version ?? null);

        return response;
    }

    public async deleteKeyBackup(version?: string): Promise<void> {
        const path = version ? `/room_keys/version/${version}` : "/room_keys/version";
        await this.http.authedRequest(Method.Delete, path);

        this.keyBackupVersion = null;
        await this.store.deleteItem("key_backup_version");
    }

    public async uploadRoomKeyBackup(
        version: string,
        roomId: string,
        sessionId: string,
        data: Record<string, unknown>,
    ): Promise<void> {
        await this.http.authedRequest(
            Method.Put,
            `/room_keys/backup/${version}/rooms/${roomId}/sessions/${sessionId}`,
            undefined,
            data,
        );
    }

    public async uploadRoomKeysBackup(
        version: string,
        rooms: Record<string, Record<string, Record<string, unknown>>>,
    ): Promise<void> {
        await this.http.authedRequest(Method.Put, `/room_keys/backup/${version}/keys`, undefined, { rooms });
    }

    public async getRoomKeyBackup(
        version: string,
        roomId: string,
        sessionId: string,
    ): Promise<Record<string, unknown>> {
        return this.http.authedRequest(
            Method.Get,
            `/room_keys/backup/${version}/rooms/${roomId}/sessions/${sessionId}`,
        );
    }

    public async getRoomKeysBackup(version: string): Promise<Record<string, Record<string, Record<string, unknown>>>> {
        return this.http.authedRequest(Method.Get, `/room_keys/backup/${version}/keys`);
    }

    public async deleteRoomKeyBackup(version: string, roomId?: string, sessionId?: string): Promise<void> {
        let path = `/room_keys/backup/${version}`;
        if (roomId) {
            path += `/rooms/${roomId}`;
            if (sessionId) {
                path += `/sessions/${sessionId}`;
            }
        }
        await this.http.authedRequest(Method.Delete, path);
    }

    public getKeyBackupVersion(): string | null {
        return this.keyBackupVersion;
    }

    private async saveKeys(): Promise<void> {
        const deviceKeys = Array.from(this.deviceKeys.entries());
        const oneTimeKeys = Array.from(this.oneTimeKeys.entries());

        await this.store.setItem("crypto_device_keys", deviceKeys);
        await this.store.setItem("crypto_one_time_keys", oneTimeKeys);
    }

    private async loadKeys(): Promise<void> {
        try {
            const deviceKeys = await this.store.getItem<Array<[string, IDeviceKeys]>>("crypto_device_keys");
            if (deviceKeys) {
                this.deviceKeys = new Map(deviceKeys);
            }

            const oneTimeKeys = await this.store.getItem<Array<[string, IOneTimeKey]>>("crypto_one_time_keys");
            if (oneTimeKeys) {
                this.oneTimeKeys = new Map(oneTimeKeys);
            }

            this.keyBackupVersion = await this.store.getItem("key_backup_version");
        } catch (error) {
            logger.warn("Failed to load crypto keys:", error);
        }
    }
}
